import triton
import triton.language as tl


@triton.jit
def sum_std_kernel(
    input_ptr, output_ptr,
    n_elements,
    dim: int,
    keepdim: bool,
    dtype: torch.dtype,
    correction: int,
):
    pid = tl.program_id(axis=0)
    offsets = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements

    input = tl.load(input_ptr + offsets, mask=mask)

    if dim is None:
        sum_val = tl.sum(input, axis=-1)
    else:
        sum_val = tl.sum(input, axis=dim)

    std_val = tl.sqrt(sum_val / (n_elements - correction))

    if keepdim:
        output = tl.expand_dims(std_val, axis=dim)
    else:
        output = std_val

    out_ptrs = output_ptr + offsets
    tl.store(out_ptrs, output, mask=mask)


def sum_std(input: torch.Tensor, dim=None, keepdim=False, dtype=None, correction=1, out=None) -> torch.Tensor:
    if dtype is not None:
        input = input.to(dtype)

    n_elements = input.numel()
    grid = lambda meta: (triton.cdiv(n_elements, meta['BLOCK_SIZE']),)
    sum_std_kernel[grid](input, out, n_elements, dim, keepdim, dtype, correction)

    if out is not None:
        return out
    else:
        return torch.empty_like(input)

