@triton.jit
def lu_kernel(
    A_ptr, P_ptr, L_ptr, U_ptr,
    m, n,
    BLOCK_SIZE: tl.constexpr,
):
    pid = tl.program_id(axis=0)
    row_idx = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)

    for i in range(row_idx, min(m, row_idx + BLOCK_SIZE)):
        # Compute the pivot
        pivot = A_ptr[i * n + i]
        if pivot == 0:
            raise ValueError("Pivot is zero at row {}".format(i))

        # Apply the pivot to the rest of the row
        for j in range(i + 1, min(m, i + BLOCK_SIZE)):
            multiplier = A_ptr[j * n + i] / pivot
            A_ptr[j * n + i] = multiplier
            for k in range(i + 1, min(n, i + BLOCK_SIZE)):
                A_ptr[j * n + k] -= multiplier * A_ptr[i * n + k]

        # Store the pivot in P
        if P_ptr is not None:
            P_ptr[i * m + i] = pivot

        # Store the lower triangular matrix L
        if L_ptr is not None:
            for j in range(i + 1, min(m, i + BLOCK_SIZE)):
                L_ptr[j * m + i] = A_ptr[j * n + i]

        # Store the upper triangular matrix U
        if U_ptr is not None:
            for j in range(i + 1, min(n, i + BLOCK_SIZE)):
                U_ptr[i * n + j] = A_ptr[i * n + j]


