        U = torch.empty((m, n), dtype=A.dtype, device=A.device)

    if out is not None:
        P, L, U = out

    grid = lambda meta: (triton.cdiv(m, meta['BLOCK_SIZE']),)
    lu_kernel[grid](A, P, L, U, m, n, BLOCK_SIZE=1024)

    return P, L, U

