def gelu_kernel(
    input_ptr, output_ptr,
    n_elements,
    BLOCK_SIZE: tl.constexpr,
):
    pid = tl.program_id(axis=0)
    offsets = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements

    x = tl.load(input_ptr + offsets, mask=mask)
    if approximate == 'exact':
        gelu_x = 0.5 * x * (1 + torch.tanh(x * np.sqrt(2)))
    elif approximate == 'approximate':
        gelu_x = 0.5 * x * (1 + torch.tanh(x * np.sqrt(2)) / np.sqrt(2))
    else:
        raise ValueError("Invalid approximation method")

    tl.store(output_ptr + offsets, gelu_x, mask=mask)


def min_gelu(input: torch.Tensor, dim=None, keepdim=False, approximate='none', out=None) -> torch.Tensor:
    if out is None:
        out = torch.empty_like(input)

    n_elements = input.numel()
    grid = lambda meta: (triton.cdiv(n_elements, meta['BLOCK_SIZE']),)
    gelu_kernel[grid](input, out, n_elements, BLOCK_SIZE=1024)

    if dim is not None:
        if keepdim:
            return torch.min(out, dim=dim, keepdim=True)
        else:
            return torch.min(out, dim=dim)
    else:
        return out

