def conv2d_relu_kernel(
    input_ptr, weight_ptr, bias_ptr,
    output_ptr,
    n_batches, in_channels, iH, iW,
    out_channels, kH, kW,
    stride=1, padding=0, dilation=1, groups=1, inplace=False,
):
    pid = tl.program_id(axis=0)
    batch_offset = pid * (n_batches // BLOCK_SIZE) * BLOCK_SIZE
    row_offsets = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)

    for i in range(BLOCK_SIZE):
        input_row = input_ptr + batch_offset + i * iH * iW
        weight_col = weight_ptr + i * kW * kH
        bias_col = bias_ptr + i

        # Convolution
        conv_result = tl.zeros((out_channels, kH, kW), dtype=tl.float32)
        for kh in range(kH):
            for kw in range(kW):
                for ih in range(iH):
                    for iw in range(iW):
                        input_val = tl.load(input_row + (ih * iW + iw) * in_channels, mask=True)
                        weight_val = tl.load(weight_col + (kh * kW + kw) * in_channels // groups, mask=True)
                        conv_result += input_val * weight_val

        # ReLU
        relu_result = tl.zeros((out_channels, kH, kW), dtype=tl.float32)
        for kh in range(kH):
            for kw in range(kW):
                for ih in range(iH):
                    for iw in range(iW):
                        relu_result += tl.where(conv_result[ih * iW + iw] > 0, conv_result[ih * iW + iw], 0)

        # Store result
        output_row = output_ptr + batch_offset + i * kH * kW
        for kh in range(kH):
            for kw in range(kW):
                for ih in range(iH):
                    for iw in range(iW):
                        tl.store(output_row + (kh * kW + kw) * out_channels, relu_result[ih * iW + iw], mask=True)


